                  Örnek: Sinüs Tablosu Oluşturma 



sinus_tablosu.mf = fopen(&#039;sinus.txt&#039;, &#039;w&#039;);
fprintf(f, &#039;Derece\tSinus\n&#039;);
for d = 0:30
    s = sin(pi * d / 180);
